func geomSum(r, n int64) int64 {
	if n == 0 {
		return 0
	}
	if r%MOD == 1 {
		return n % MOD
	}
	num := (modPow(r%MOD, n, MOD) - 1 + MOD) % MOD
	denInv := modInv((r - 1 + MOD) % MOD)
	return num * denInv % MOD
}

